def get_spectrum(n, support):
    """
    Compute spectrum of a given support of an n-bit vector.
    """
    spectrum = {}

    def dist(i, j):
        i, j = max(i, j), min(i, j)
        d1 = i - j
        d2 = n - d1
        return min(d1, d2)

    for i, s1 in enumerate(support):
        for s2 in support[i + 1 :]:
            d = dist(s1, s2)
            if d not in spectrum:
                spectrum[d] = 0
            spectrum[d] += 1
    return spectrum


@dataclass
class KeyFromSpectrumAlgorithmParams:
    """
    Parameters used by the key recovery algorithm (mostly thresholds and tweaks)
    """

    phase1_iterations: int
    top_selected: int
    min_support_size: int


@dataclass
class SpectrumInfo:
    """
    Main class responsible for initializing spectrum parameters for key recovery.
    n: int              # Bit length of the key vector
    known_in: set       # Distances that are known to be inside the spectrum (may have a few errors)
    known_out: set      # Distances that are known to be outside the spectrum (may have a few errors)
    param_omega: int    # Weigth of the key vector
    recovery_parameters: KeyFromSpectrumAlgorithmParams # Parameters for key recovery
    """

    n: int  # Bit length of the key vector
    known_in: set  # Distances that are known to be inside the spectrum (may have a few errors)
    known_out: set  # Distances that are known to be outside the spectrum (may have a few errors)
    param_omega: int  # Weigth of the key vector
    recovery_parameters: KeyFromSpectrumAlgorithmParams  # Parameters for key recovery

    def modpos(self, pos):
        """
        Get `pos mod self.n`.
        """
        return pos % self.n

    def get_null_for_partial_support(self, support):
        """
        Get set of null entries that can be inferred for a given support, assuming `known_out` is the
        set of invalid distances. That is: for each element `s` of the support, it returns all
        entries that should be zero using the fact that `s + d` and `s - d` should not be 1
        for all `d` in `known_out`.
        """
        null = set()
        for s in support:
            for d in self.known_out:
                null.add(self.modpos(s + d))
                null.add(self.modpos(s - d))
        return null

    def get_null_rating_for_partial_support(self, support):
        """
        Similar to `get_null_for_partial_support`, but gives the "scores" representing how likely
        each position is to be 0. This is useful for the final key reconstruction part that
        does not require `known_out` to be completely correct: it can contain a few distances
        that are actually in the spectrum.
        """
        null = {}
        for s in support:
            for d in self.known_out:
                s1 = self.modpos(s + d)
                s2 = self.modpos(s - d)

                if s1 in support:
                    continue
                if s2 in support:
                    continue

                if s1 not in null:
                    null[s1] = 0
                if s2 not in null:
                    null[s2] = 0
                null[s1] += 1
                null[s2] += 1

        return null

    def dist(self, i, j):
        """
        Computes circular distance between `i` and `j`.
        """
        i, j = max(i, j), min(i, j)
        d1 = i - j
        d2 = self.n - d1
        return min(d1, d2)

    def recover(self, support=None):
        """
        Runs one iteration of key recovery!
        Important: this does not fully recover the key: you have to run it multiple times, in general, until
        a sufficiently large (i.e. length OMEGA) candidate key is found, and you have to check if it is
        indeed the key. Remember to also check the reflection of an output support.
        """

        # This lets you start with a partially known support. Otherwise it starts with candidate {0, 0 + d}, for
        # some `d` that is in the spectrum (`d in known_in`).
        if support == None:
            support = {0, random.choice(self.known_in)}

        # Main loop: try to find a large support, one position at a time
        while len(support) < self.param_omega:
            null = self.get_null_for_partial_support(
                support
            )  # Set of null entries for a given support
            possible = (
                set(range(self.n)) - support - null
            )  # Set of possible positions to be added in next iter
            if not possible:
                break  # Nothing can be added... breaking

            # Initialize the scores for each candidate next position `p`.
            #   -> This will depend on how problematic each `p` is according to what `known_out` predicts
            scores = {}
            for p in possible:
                # If in Phase1: Tries to start cleanly with all distances in the spectrum `known_in`
                if len(support) < self.recovery_parameters.phase1_iterations:
                    valid = True
                    for s in support:
                        if self.dist(p, s) not in self.known_in:
                            valid = False
                            break
                    if not valid:
                        continue

                # null_p: the positions that will be have to be 0 if `p` is added (assuming `known_out` is correct)
                null_p = {self.modpos(p + d) for d in self.known_out}
                null_p.add(self.modpos(p - d) for d in self.known_out)

                # Computes score based on what `p` will differ from the status quo
                score = len(null_p.intersection(null))
                scores[p] = score

            # Find best score: this gives the candidate `p` that divergest the least
            best = sorted(scores.items(), key=lambda x: x[1])
            if not best:
                break

            # Add candidate `p`
            support.add(
                random.choice(best[-self.recovery_parameters.top_selected :])[0]
            )

        # Last phase: sometimes (or most of the times), not all OMEGA entries are found
        #  -> Only enters if support is sufficiently large (i.e. > `min_support_size`)
        if self.recovery_parameters.min_support_size <= len(support) < self.param_omega:
            n_missing = self.param_omega - len(
                support
            )  # number of missing entries in the support
            null_rating = self.get_null_rating_for_partial_support(
                support
            )  # get scores for each nullified position

            # `known_support` can have a few mistakes. This means that some positions that could be nullified by the
            # mistakes will likely not be backed by right outside distances in `known_support`
            unlikely_null_with_rating = sorted(null_rating.items(), key=lambda k: k[1])[
                :n_missing
            ]
            # Add the most unlikely null entries to the support
            support = support.union([u[0] for u in unlikely_null_with_rating])

        sorted_support = sorted(support)
        # Info print:
        print(f"[*] Found length {len(support)}:", sorted_support)

        return sorted_support

    def test_if_is_shifted_key(self, known_target_key_support, candidate_key_support):
        known_target_key_support = sorted(known_target_key_support)
        candidate_key_support = sorted(candidate_key_support)

        target_spec = get_spectrum(self.n, known_target_key_support)
        candidate_spec = get_spectrum(self.n, candidate_key_support)

        if target_spec != candidate_spec:
            return False

        shift = None
        dist = None
        for i in range(len(known_target_key_support)):
            d = self.dist(known_target_key_support[i], known_target_key_support[i - 1])
            if target_spec[d] == 1:
                dist, shift = d, known_target_key_support[i - 1]
                break

        shift2 = None
        for i in range(len(candidate_key_support)):
            if (
                self.dist(candidate_key_support[i], candidate_key_support[i - 1])
                == dist
            ):
                shift2 = candidate_key_support[i - 1]
                break

        shifted_known_target_key_support = sorted(
            [(s - shift) % self.n for s in known_target_key_support]
        )
        shifted_candidate_key_support = sorted(
            [(s - shift2) % self.n for s in candidate_key_support]
        )

        return shifted_known_target_key_support == shifted_candidate_key_support

    def reflect_support(self, support):
        return [(-i) % self.n for i in support]

    def test_if_recovery_works(self, real_key_support, n_tries=100, seed=0):
        found_key = False

        # For reproducibility of key recovery attacks
        random.seed(seed)

        w = len(real_key_support)

        x = None
        base_x = None

        # We keep track of the last guesses to prevent the search to get stuck into a bad set
        n_last_gueeses_to_keep_track = 50
        last_guesses = [None] * n_last_gueeses_to_keep_track
        for i in range(n_tries):
            x = self.recover(support=base_x)

            if len(x) == w:
                found_key = self.test_if_is_shifted_key(x, real_key_support)
                if not found_key:
                    x = self.reflect_support(x)
                    found_key = self.test_if_is_shifted_key(x, real_key_support)

            if found_key:
                break

            last_guesses[i % n_last_gueeses_to_keep_track] = tuple(sorted(x))

            if len(set(last_guesses)) < n_last_gueeses_to_keep_track // 2:
                base_x = None  # If it is stuck into a set that does not provide much variane, restart with empty guess
            else:
                base_x = set(
                    [0] + random.sample(x[1:], len(x) // 2)
                )  # keep a bunch of entries of the last guess

        print()
        print("=" * 80)
        if found_key:
            print("[+] Key found : ) ")
            print("    Support (likely rotated):")
            print("   ", x)
        else:
            print("[-] Not found : (")
        print("=" * 80)

        print()

        return found_key

    def test_if_recovery_works_given_expected_spectrum(
        self, real_key_spectrum, w, n_tries=100, seed=0
    ):
        found_key = False

        # For reproducibility of key recovery attacks
        random.seed(seed)

        x = None
        base_x = None

        # We keep track of the last guesses to prevent the search to get stuck into a bad set
        n_last_gueeses_to_keep_track = 50
        last_guesses = [None] * n_last_gueeses_to_keep_track
        for i in range(n_tries):
            # print(i)
            x = self.recover(support=base_x)

            spectrum_x = get_spectrum(self.n, x)
            if spectrum_x == real_key_spectrum:
                found_key = True
                break

            last_guesses[i % n_last_gueeses_to_keep_track] = tuple(sorted(x))

            if len(set(last_guesses)) < n_last_gueeses_to_keep_track // 2:
                base_x = None  # If it is stuck into a set that does not provide much variane, restart with empty guess
            else:
                base_x = set(
                    [0] + random.sample(x[1:], len(x) // 2)
                )  # keep a bunch of entries of the last guess

        print()
        print("=" * 80)
        if found_key:
            print("[+] Key found : ) ")
            print("    Support (likely rotated):")
            print("   ", x)
        else:
            print("[-] Not found : (")
        print("=" * 80)

        return found_key


