def estimate_good_attack_parameters_for_hqc(
    n_assumed_out,
    n_false_out,
    n_assumed_in,
    n_false_in,
    n=17669,
    weight=66,
    n_tries=100,
):
    n_known_in = math.ceil(n_assumed_out / 3.6)  # Heuristic assumption

    secret_support = random.sample(range(n), weight)
    secret_spectrum = get_spectrum(n, secret_support)

    all_distances_out = [i for i in range(n // 2 + 1) if i not in secret_spectrum]
    all_distances_in = list(secret_spectrum)

    n_assumed_out = min(n_assumed_out, len(all_distances_out))
    n_assumed_in = min(n_known_in, len(all_distances_in))

    false_in = random.sample(all_distances_out, n_false_in)
    false_out = random.sample(all_distances_in, n_false_out)

    all_distances_out = list(set(all_distances_out) - set(false_in))
    all_distances_in = list(set(all_distances_in) - set(false_out))

    distances_out = random.sample(all_distances_out, n_assumed_out - n_false_out)
    distances_in = random.sample(all_distances_in, n_known_in - n_false_in)

    print(f"{len(all_distances_in)=}")
    print(f"{len(all_distances_out)=}")

    si = SpectrumInfo(
        n=n,
        known_in=distances_in,
        known_out=distances_out,
        param_omega=weight,
        recovery_parameters=KeyFromSpectrumAlgorithmParams(6, 10, 55),
    )

    si.test_if_recovery_works(secret_support, n_tries=n_tries)


def analyze_dataframe(df):

    print("For (r1, y):")
    for v in sorted(df.spec_r2_estimator.unique()):
        n_in_below = len(df[(df.spec_r2_estimator <= v) & (df.spec_x > 0)])
        n_out_below = len(df[(df.spec_r2_estimator <= v) & (df.spec_x == 0)])
        n_in_above = len(df[(df.spec_r2_estimator >= v) & (df.spec_x > 0)])
        n_out_above = len(df[(df.spec_r2_estimator >= v) & (df.spec_x == 0)])
        print(f"{v=}, {n_in_below=}, {n_out_below=}, {n_in_above=}, {n_out_above=}")

    print()
    print("For (r2, x):")
    for v in sorted(df.spec_r1_estimator.unique()):
        n_in_below = len(df[(df.spec_r1_estimator <= v) & (df.spec_y > 0)])
        n_out_below = len(df[(df.spec_r1_estimator <= v) & (df.spec_y == 0)])
        n_in_above = len(df[(df.spec_r1_estimator >= v) & (df.spec_y > 0)])
        n_out_above = len(df[(df.spec_r1_estimator >= v) & (df.spec_y == 0)])
        print(f"{v=}, {n_in_below=}, {n_out_below=}, {n_in_above=}, {n_out_above=}")


def parse_fia_simulation_csv(datafile):
    list_converter = lambda x: map(
        int,
    )

    df_xy = pd.read_csv(
        datafile,
        converters={
            "x": literal_eval,
            "y": literal_eval,
        },
        nrows=1,
    )

    x = df_xy.x[0]
    y = df_xy.y[0]

    df = pd.read_csv(datafile, skiprows=2)

    return (x, y), df


def run_key_recovery_against_real_dataset_hqc(
    datafile, n_challenges, n_distances_in, n_distances_out, seed=0
):
    random.seed(seed)

    (x, y), df = parse_fia_simulation_csv(datafile)

    df = df[df.n_challenges == n_challenges]

    sorted_r2_estimators = sorted(df.spec_r2_estimator)
    threshold_in = sorted_r2_estimators[n_distances_in]
    threshold_out = sorted_r2_estimators[-n_distances_out]

    distances_in = random.sample(
        list(df[df.spec_r2_estimator <= threshold_in].distance), n_distances_in
    )
    distances_out = random.sample(
        list(df[df.spec_r2_estimator >= threshold_out].distance), n_distances_out
    )

    # print(distances_in)
    # print(distances_out)
    n = len(df) * 2 + 1
    weight = len(x)
    print(f"{(n, weight) = }")
    print(df.head())
    print(f"{threshold_in=}")
    print(f"{threshold_out=}")

    si = SpectrumInfo(
        n=n,
        known_in=distances_in,
        known_out=distances_out,
        param_omega=weight,
        recovery_parameters=KeyFromSpectrumAlgorithmParams(7, 10, 20),
    )

    return si.test_if_recovery_works(x, n_tries=1000, seed=seed)


def run_key_recovery_against_real_dataset_bike(
    datafile, weight, n_challenges, n_distances_in, n_distances_out, seed=0
):
    random.seed(seed)

    df = pd.read_csv(datafile)

    df = df[df.n_challenges == n_challenges]

    # TODO: Consider e1 estimators for h1 too
    sorted_e0_estimators = sorted(df.spec_e0_estimator)
    threshold_in = sorted_e0_estimators[n_distances_in]
    threshold_out = sorted_e0_estimators[-n_distances_out]

    distances_in = random.sample(
        list(df[df.spec_e0_estimator <= threshold_in].distance), n_distances_in
    )
    distances_out = random.sample(
        list(df[df.spec_e0_estimator >= threshold_out].distance), n_distances_out
    )

    # print(distances_in)
    # print(distances_out)
    n = len(df) * 2 + 1
    print(f"{(n, weight) = }")
    print(df.head())
    print(f"{threshold_in=}")
    print(f"{threshold_out=}")

    si = SpectrumInfo(
        n=n,
        known_in=distances_in,
        known_out=distances_out,
        param_omega=weight,
        recovery_parameters=KeyFromSpectrumAlgorithmParams(5, 10, 45),
    )

    real_key_spectrum = {
        i: v for i, v in zip(range(1, n // 2 + 1), df.spec_h0) if v > 0
    }
    return si.test_if_recovery_works_given_expected_spectrum(
        real_key_spectrum, weight, n_tries=1000, seed=seed
    )


def test_if_key_recovery_is_possible_for_hqc_challenge(datafile):
    # We know that the attack for for these parameters
    # estimate_good_attack_parameters_for_hqc(4000)
    n_known_out = 4000
    n_known_in = math.ceil(n_known_out / 3.6)  # Heuristic assumption

    full_df = pd.read_csv(datafile)

    for n_challenges in full_df.n_challenges.unique():
        df = full_df[full_df.n_challenges == n_challenges]
        n = len(df)
        sorted_e0_estimators = sorted(df.spec_r2_estimator)
        limit_below_out = sorted_e0_estimators[n - n_known_out - 1]
        limit_above_in = sorted_e0_estimators[n_known_in]

        if len(df[(df.spec_r2_estimator >= limit_below_out) & (df.spec_x != 0)]) > 0:
            print(f"{n_challenges=}: noo : (")
            continue

        if len(df[(df.spec_r2_estimator <= limit_above_in) & (df.spec_x == 0)]) > 0:
            print(f"{n_challenges=}: noo : (")
            continue

        print(f"{n_challenges=}: yes! : )")
        break


